contract InvMutTest {
    C c;
    address token;

    constructor(C _c) { c = _c; }

    // params: distributor candidate, reward token address, amount to notify
    function run(address distributor, address _rewardToken, uint256 amount) public payable {
        require(address(c) != address(0));

        // ensure reward token is added first by owner: c was freshly deployed with this test contract as owner
        // addReward must be called by owner (this contract is owner since constructor of C used msg.sender)
        // Call addReward only if rewardData for token unknown; we can call unconditionally because addReward will revert if exists.
        bool addedReverted;
        try c.addReward(_rewardToken) {
            addedReverted = false;
        } catch {
            addedReverted = true;
        }

        // set rewardDistributor to distributor (onlyOwner) — this contract is owner so should succeed
        bool setDistReverted;
        try c.setRewardDistributor(distributor) {
            setDistReverted = false;
        } catch {
            setDistReverted = true;
        }

        // record before values: contract token balance and period finish
        uint256 beforeBalance = IERC20(_rewardToken).balanceOf(address(c));
        uint40 beforeFinish = c.rewardPeriodFinish(_rewardToken);

        // Now attempt to call notifyRewardAmount from distributor by invoking through c as if msg.sender==distributor is impossible here.
        // Instead we check behavior: call notifyRewardAmount from this contract when it's not distributor must revert; when it is distributor must succeed.
        // So we simulate both cases by: first try as wrong caller (this contract) — should revert unless distributor equals this contract
        bool notifyRevertedWhenNotDistributor;
        try c.notifyRewardAmount(_rewardToken, amount) {
            notifyRevertedWhenNotDistributor = false;
        } catch {
            notifyRevertedWhenNotDistributor = true;
        }

        // If distributor equals this contract address, then notify should not revert and contract balance must increase by amount
        // Otherwise notify should have reverted (require(msg.sender == rewardDistributor)) and no balance change should have happened.
        uint256 afterBalance = IERC20(_rewardToken).balanceOf(address(c));
        uint40 afterFinish = c.rewardPeriodFinish(_rewardToken);

        // General rule: (1) If msg.sender equals distributor param then notify call (we made) should not revert and balance increased by amount and periodFinish >= now + C.DURATION - but we can't read DURATION constant
        // We can check that periodFinish >= beforeFinish and if amount>0 then afterBalance >= beforeBalance + (notify succeeded ? amount : 0).
        // Also if notify reverted then distributor != msg.sender (unless amount==0 or token unknown) — but we avoid depending on that.

        // Construct the assertion capturing intended invariant:
        // If our notify did not revert then afterBalance == beforeBalance + amount and afterFinish >= beforeFinish && afterFinish > beforeFinish (period extended when amount>0)
        // If our notify reverted then afterBalance == beforeBalance and afterFinish == beforeFinish
        assert(
            (notifyRevertedWhenNotDistributor && afterBalance == beforeBalance && afterFinish == beforeFinish)
            ||
            (!notifyRevertedWhenNotDistributor && afterBalance == beforeBalance + amount && afterFinish >= beforeFinish)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: who to stake for, amount to stake
    function run(address forAddr, uint256 amount) public payable {
        require(address(c) != address(0));

        // Precondition: this contract must have enough stakingToken balance and allowance so staking can succeed.
        // We cannot call ERC20 functions here (not allowed to declare token interface), but assume test harness will arrange token transfers/allowances.
        // Call stakeFor as a top-level state-changing call and catch revert status.
        bool stakeReverted;
        try c.stakeFor(forAddr, amount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // Observe public state after the call
        uint256 total = c.totalSupply();
        uint256 bal = c.balanceOf(forAddr);

        // General rule:
        // If stakeFor did not revert then totalSupply >= amount and balanceOf(forAddr) >= amount.
        // If stakeFor reverted then totalSupply and balance remain unchanged from some non-decreasing property we cannot observe before-call safely, so require only that a successful stake implies increases.
        assert(stakeReverted || (total >= amount && bal >= amount));
    }

    receive() external payable {}
}

