contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call notifyRewardAmount from this contract, so this contract must be set as rewardDistributor by the deployer of c.
    // The test takes the reward token address and an amount to notify; it transfers tokens to this contract and calls notifyRewardAmount.
    // It then asserts that address(c).balance for that token (observed via IERC20.balanceOf) increased by the amount provided and that the call did not revert.

    function run(address rewardToken, uint256 amount) public payable {
        require(rewardToken != address(0), "rewardToken nonzero");
        require(amount > 0, "amount>0");

        IERC20 token = IERC20(rewardToken);

        // Record c's token balance before
        uint256 before = token.balanceOf(address(c));

        // Transfer `amount` tokens from msg.sender (which in checks will be the test harness EOA) to this contract so we can forward them.
        // The harness must ensure this contract has tokens and has allowance if needed; here we try to pull via transferFrom.
        // First, attempt to pull tokens to this contract. If this fails the try/catch will set reverted.
        bool reverted = false;
        // Approve is not possible here since we don't control token internals; instead we assume the test environment will pre-fund this contract.

        // Ensure this contract has at least `amount` tokens. If not, revert the test precondition so the checker can avoid meaningless runs.
        require(token.balanceOf(address(this)) >= amount, "test contract needs tokens");

        // Now call notifyRewardAmount. It must be called by rewardDistributor. The harness should have set rewardDistributor to this contract address.
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = token.balanceOf(address(c));

        // General rule: if notifyRewardAmount did not revert, c's token balance increased by exactly `amount`.
        assert(reverted || after == before + amount);
    }

    receive() external payable {}
}

