    // single public entry for property-based testing
    function run(address staker, uint256 amount) public payable {
        require(staker != address(0), "nonzero staker");
        // Precondition: this contract must have enough staking tokens approved by msg.sender (the deployer of c may set token balances externally in harness)
        // Observe before-values
        uint256 beforeTotal = c.totalSupply();
