contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: distributor must be msg.sender when notifyRewardAmount is called from this test,
    // so we take distributor as input and rely on c being constructed with that distributor.
    // Provide the reward token address and an amount to notify; amount > 0.
    function run(address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount must be > 0");
        // Precondition: reward token must have been added by owner before; we cannot modify owner here.
        // We observe current periodFinish and contract balance, then attempt to call notifyRewardAmount.

        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBalance = address(c).balance;

        // If call did not revert, then periodFinish must strictly increase (be > before) and contract balance increased by amount.
        // If it reverted, then we assert that neither condition holds simultaneously (i.e., at least one of them failed),
        // so the overall assertion is: either reverted, or (afterFinish > beforeFinish && afterBalance >= beforeBalance + amount).
        // Use >= for balance to be tolerant if token transfer logic behaves oddly for native Ether (though C uses ERC20 transfers),
        // but require strict increase of periodFinish.
        assert(reverted || (uint256(afterFinish) > uint256(beforeFinish) && afterBalance >= beforeBalance + amount));
    }

    receive() external payable {}
}

