contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // We need the test to take parameters: from (approver) is msg.sender of stakeFor call inside c;
    // but in this harness the InvMutTest contract is the msg.sender for c calls. We'll simulate
    // staking by first transferring tokens to this contract and approving c to pull them.
    // Parameters: uint256 initialBalance - tokens to give this test contract; uint256 stakeAmount - amount to stake
    function run(uint256 initialBalance, uint256 stakeAmount) public payable {
        require(initialBalance <= type(uint256).max / 2);
        require(stakeAmount <= type(uint256).max / 2);

        // Setup: ensure this contract has initialBalance tokens by calling token.transfer on the staking token
        // We can only call public functions on c and token; token is an IERC20 external contract.
        // Transfer tokens to this contract must be done by calling token.transfer from the token contract
        // but we cannot mint. However the checker deploys c fresh but not token; token may be a test token that allows transfers from owner (c owner) -- to be conservative we only proceed if token.balanceOf(address(this)) can be increased by a previous setup transfer from the test environment.
        // To avoid assumptions about external mint, we require that initialBalance equals token.balanceOf(address(this)) or else we skip staking by setting stakeAmount to 0.

        uint256 beforeBal = c.balanceOf(address(this));
        uint256 beforeTotal = c.totalSupply();
        uint256 myTokenBal = token.balanceOf(address(this));

        // If we do not hold enough staking tokens to approve stakeAmount, adjust stakeAmount to zero so stakeFor will revert on amount==0 check if stakeAmount==0? stakeFor requires _amount>0, so calling with 0 would revert. To exercise successful stake we require we have sufficient token balance and stakeAmount>0 and also that this contract approves c.
        bool willAttemptStake = (stakeAmount > 0 && myTokenBal >= stakeAmount);

        if (willAttemptStake) {
            // Approve c to pull stakeAmount
            token.approve(address(c), stakeAmount);
        }

        bool reverted;
        // perform the stakeFor call: stakeFor(msg.sender, stakeAmount) will be invoked as c.stakeFor(address,uint256)
        // We call stakeFor directly; it will pull tokens from this contract via safeTransferFrom.
        try c.stakeFor(address(this), stakeAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = c.balanceOf(address(this));
        uint256 afterTotal = c.totalSupply();

        // General rule: if the stake call did not revert, then totalSupply increased by stakeAmount and balance increased by stakeAmount.
        // If it reverted, then neither changed (they remain equal to before). We assert the general relation covering both cases.
        assert(
            (!reverted && afterTotal == beforeTotal + stakeAmount && afterBal == beforeBal + stakeAmount)
            || (reverted && afterTotal == beforeTotal && afterBal == beforeBal)
        );
    }

    // no special receive needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // parameters:
    // initialApproveAmount: how many staking tokens this contract will approve c to pull
    // stakeAmount: amount passed to stakeFor
    function run(uint256 initialApproveAmount, uint256 stakeAmount) public payable {
        // read-before values (view calls only)
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(address(this));

        // Prepare approval by calling stakingToken().approve on the token contract directly is not allowed here
        // (we must only call c and public functions). However the stakingToken is an IERC20 public variable on c,
        // accessible as c.stakingToken(). We call approve on that token (external call) to allow c to pull tokens.
        // This is a state-changing external call but not a call on c, which is allowed.
        IERC20 token = c.stakingToken();
        // Approve c to pull initialApproveAmount (may succeed or revert depending on token implementation and balances)
        // We capture revert using try/catch around the token.approve call; the stakeFor call below must be a top-level statement.
        bool approveReverted = false;
        try token.approve(address(c), initialApproveAmount) returns (bool ok) {
            // approved (ok may be false but approve returned successfully) - we ignore ok here
        } catch {
            approveReverted = true;
        }

        // Now attempt the stakeFor call as a top-level statement and capture whether it reverts.
        bool stakeReverted;
        try c.stakeFor(address(this), stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // read-after values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(address(this));

