        // The test contract must have stakingToken approved by the staker for stakeFrom to work in general
        // but we cannot perform external approvals here. We will instead operate as the staker by calling
        // stakeFor on c from this contract (msg.sender for c calls is this contract). Use stakeFor to credit `staker`.
        // To do that, this contract must hold tokens; we cannot mint tokens here. So instead, we invoke only
        // view/read functions to observe claimableRewards around a withdraw triggered via migrateWithdraw which
        // calls _withdrawFor and transfers tokens from c to msg.sender. migrateWithdraw is only callable by migrator.
        // To create a deterministic, observable scenario using only public surface that always exists, we
        // will exploit withdraw (called by the user) — but msg.sender for those calls will be this test contract.
        // Therefore we interpret `staker` parameter as ignored for the actual c calls: we act as this contract as the staker.

        // Preconditions: ensure there is at least stakeAmount recorded for this contract by attempting to stake via stakeFor.
        // However, staking requires transferring stakingToken from msg.sender to c. We cannot guarantee tokens, so
        // instead we only perform the property when stake/withdraw amounts are such that withdrawAmount <= balanceOf(this).
        // Read current balance and claimable rewards for this contract (the acting staker)

        uint256 beforeBalance = c.balanceOf(address(this));

        // snapshot claimable rewards for all known reward tokens by reading rewardTokens length and per-index via rewardTokens (public array has getter)
        // rewardTokens is public: c.rewardTokens(uint256) exists. But length isn't directly exposed; however rewardTokens is a public array so its getter reverts if out of bounds.
        // We try indices 0..7 as a bounded exploration; the assert must be general so we quantify over tokens we successfully read.

        // Collect before claimable values for indices that exist
        uint256[8] memory beforeClaimables;
        bool[8] memory exists;
        for (uint256 i = 0; i < 8; i++) {
            // try to read reward token address at i
            try c.rewardTokens(i) returns (address token) {
                exists[i] = true;
                beforeClaimables[i] = c.claimableRewards(address(this), token);
            } catch {
                exists[i] = false;
                beforeClaimables[i] = 0;
            }
        }

        // Now attempt a withdraw call as this contract. The rule we assert is: if withdraw succeeded and claim flag is false,
        // then for every reward token observed before, claimableRewards after equals before (i.e., unchanged).

        // We must ensure we do not revert inside run; catch revert via try/catch
        bool withdrewReverted = false;
        try c.withdraw(withdrawAmount, false) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // read after values for same indices
        uint256[8] memory afterClaimables;
        for (uint256 i = 0; i < 8; i++) {
            if (exists[i]) {
                address token = c.rewardTokens(i);
                afterClaimables[i] = c.claimableRewards(address(this), token);
            } else {
                afterClaimables[i] = 0;
            }
        }

        // General rule assertion:
        // If withdraw did not revert AND withdrawAmount <= beforeBalance (so withdraw could logically succeed), then
        // for every observed reward token the claimableRewards did not change when claim flag was false.
        // Note: we avoid underflow by not computing differences; we use equality.
        bool allEqual = true;
        for (uint256 i = 0; i < 8; i++) {
            if (exists[i]) {
                if (afterClaimables[i] != beforeClaimables[i]) {
                    allEqual = false;
                }
            }
        }

        assert( (withdrewReverted || withdrawAmount > beforeBalance) || allEqual );
    }

    receive() external payable {}
}

