contract InvMutTest {
    C c;
    address distributor;
    constructor(C _c) { c = _c; distributor = address(0xdead); }

    // single public function with inputs: reward token address, amount to notify, and an address to set as distributor beforehand
    function run(address rewardToken, uint256 amount, address newDistributor) public payable {
        require(newDistributor != address(0), "provide nonzero distributor");

        // Set owner to this contract is already true because the checker deploys fresh C with InvMutTest as deployer.
        // Make this contract the owner by relying on that behavior; cannot call transferOwnership here safely otherwise.

        // First, owner adds the reward token so it becomes known. addReward is onlyOwner, so this contract (owner) calls it.
        c.addReward(rewardToken);

        // Read the periodFinish before notify
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        // Set rewardDistributor to newDistributor using onlyOwner function
        c.setRewardDistributor(newDistributor);

        // Try calling notifyRewardAmount from newDistributor (which will be different msg.sender) -> should revert
        bool revertedWhenNotDistributor;
        try c.notifyRewardAmount{value: 0}(rewardToken, amount) {
            // this call is made by this contract (not newDistributor), so if it doesn't revert, mark false
            revertedWhenNotDistributor = false;
        } catch {
            revertedWhenNotDistributor = true;
        }

        // Now simulate correct distributor calling notifyRewardAmount by having this contract set distributor to itself
        c.setRewardDistributor(address(this));

        // If amount == 0 then notifyRewardAmount should revert with "No reward". Capture revert.
        bool revertedOnZero;
        try c.notifyRewardAmount{value: 0}(rewardToken, amount) {
            revertedOnZero = false;
        } catch {
            revertedOnZero = true;
        }

        // After a successful notify (i.e., when distributor==this and amount>0), the periodFinish should increase to > beforeFinish.
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // Build the general assertion covering both expected revert cases and the successful advance case.
        // Assert: if caller was not distributor then the prior call reverted; and if distributor==this and amount>0 then afterFinish > beforeFinish; and if amount==0 then notify reverted.
        assert(
            // the earlier attempt when distributor was newDistributor (different from this) must have reverted
            (revertedWhenNotDistributor == true)
            // and if amount == 0 then our notify (with distributor==this) must have reverted
            && ((amount == 0) ? (revertedOnZero == true) : (revertedOnZero == false && afterFinish > beforeFinish))
        );
    }

    receive() external payable {}
}

