contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: distributor (caller of notifyRewardAmount), rewardToken address, amount
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        // cannot meaningfully observe behavior for zero addresses as token; allow any
        // prepare: deploy must have owner = this, but c is already freshly deployed by checker
        // Owner-only setup: add rewardToken so notifyRewardAmount can recognize it — only owner can call addReward.
        // Our contract is NOT owner, so we cannot call addReward. Instead, the rule accounts for unknown token case.

        // record previous observable values
        uint256 beforeTokenBalance = IERC20(rewardToken).balanceOf(address(c));
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTokenBalance = IERC20(rewardToken).balanceOf(address(c));
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // General rule:
        // If the call did not revert then:
        //  - caller must have been the configured rewardDistributor (otherwise function should revert)
        //  - amount must be > 0 (otherwise function should revert)
        //  - reward token must have been previously added (otherwise function should revert)
        //  - the token balance of the contract increases by exactly amount
        //  - periodFinish for that token is strictly greater than the previous periodFinish
        // If the call reverted then at least one of the first three preconditions (distributor match, amount>0, token known) was false.

        // We cannot read rewardDistributor directly (it is public), so we observe it.
        address actualDistributor = c.rewardDistributor();

        assert(
            // success case: not reverted implies all expected effects
            (!reverted && actualDistributor == msg.sender && amount > 0 && beforeTokenBalance + amount == afterTokenBalance && afterFinish > beforeFinish)
            // failure case: reverted implies at least one precondition violated
            || (reverted && (actualDistributor != msg.sender || amount == 0 || beforeFinish == 0))
        );
    }

    receive() external payable {}
}

