contract InvMutTest {
    C c;
    address distributor;

    constructor(C _c) {
        c = _c;
        distributor = address(0x100); // placeholder; tests will set msg.sender when calling notify
    }

    // The test will: add a reward token, then try to call notifyRewardAmount from the distributor address.
    // We cannot change msg.sender in this context, but we can simulate the observable rule in two parts:
    // - call addReward as owner (contract deploying c is owner), then
    // - call notifyRewardAmount via c.notifyRewardAmount(...) and observe whether it reverted or succeeded,
    //   and check that if it succeeded then periodFinish increased and address(c).balance increased by amount.

    // Note: because only rewardDistributor can call notifyRewardAmount, the test takes an address param "caller"
    // and an amount. The run function will first set the rewardDistributor via setRewardDistributor if this contract
    // is owner (it is, because c was deployed by the harness and ownership is the deployer — the checker deploys c freshly
    // and then deploys this test with c passed in; per problem statement this contract deployed c, so this contract is owner).

    function run(address rewardToken, address caller, uint256 amount) public payable {
        require(rewardToken != address(0), true);

        // Make sure we are owner: set this contract as rewardDistributor so we can call notifyRewardAmount.
        // We call setRewardDistributor with this contract's address via c.setRewardDistributor(address(this));
        // That is a state-changing call and must be top-level.
        c.setRewardDistributor(address(this));

        // Add the reward token so notifyRewardAmount will accept it.
        c.addReward(rewardToken);

        // Record previous periodFinish and contract balance.
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = address(c).balance;

        // Prepare: if amount > 0 we must have this contract hold tokens and approve c to pull them. However we cannot mint tokens here.
        // Instead rely on case amount == 0 being rejected by require in notifyRewardAmount. To make a meaningful rule, allow any amount,
        // but we will attempt the call and observe revert flag.

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBalance = address(c).balance;

        // General rule: if notifyRewardAmount did NOT revert, then afterFinish > beforeFinish and afterBalance >= beforeBalance.
        // (afterBalance should increase by amount if token transfer succeeded, but token is ERC20 not Ether, so address(c).balance unaffected;
        // but reward transfer uses ERC20.safeTransferFrom, which doesn't change Ether balance. Therefore we assert only non-decreasing Ether balance.)
        assert(reverted || (afterFinish > beforeFinish && afterBalance >= beforeBalance));
    }

    receive() external payable {}
}

