    // amount is the stake amount
    function run(address from, address forAddress, uint256 amount) public payable {
        require(forAddress != address(0));
        // observe before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(forAddress);

        // perform call: since InvMutTest is the msg.sender for calls to c, but stakeFor transfers tokens from msg.sender,
        // we simulate by calling c.stakeFor(from, amount) where c will pull tokens from msg.sender (which is this contract)
        // However the function stakeFor uses msg.sender as the one providing tokens; so to exercise transferFrom behavior
        // we call stakeFor(forAddress, amount) directly (msg.sender == address(this)). The environment must arrange token approvals.

        bool reverted;
        try c.stakeFor(forAddress, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(forAddress);

        // General rule:
        // If stakeFor succeeded then totalSupply and the staker balance increased by exactly amount.
        // If stakeFor reverted then neither changed.
        assert(
            reverted
                ? (afterTotal == beforeTotal && afterBalance == beforeBalance)
                : (afterTotal == beforeTotal + amount && afterBalance == beforeBalance + amount)
        );
    }

    receive() external payable {}
}

