contract InvMutTest {
    C c;
    address token;
    address distributor;

    constructor(C _c) { c = _c; }

    // caller must be the reward distributor address when calling notifyRewardAmount; we model calls from this contract
    // _rewardsToken: token address to notify for (must have been added via addReward by owner earlier in lifecycle)
    // _amount: amount to notify and transfer
    function run(address _rewardsToken, uint256 _amount) public payable {
        require(_rewardsToken != address(0));

        // observe preconditions: record balance of reward token held by c and previous periodFinish
        uint256 beforeBalance = IERC20(_rewardsToken).balanceOf(address(c));
        uint40 beforeFinish = c.rewardPeriodFinish(_rewardsToken);

        // perform call as the distributor: first set this contract as distributor by calling setRewardDistributor via owner - but we cannot be owner
        // Instead, attempt the call and capture revert. The contract requires msg.sender == rewardDistributor, so two cases:
        bool reverted;
        try c.notifyRewardAmount(_rewardsToken, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = IERC20(_rewardsToken).balanceOf(address(c));
        uint40 afterFinish = c.rewardPeriodFinish(_rewardsToken);

        // GENERAL RULE:
        // If notifyRewardAmount reverted then balances/finish may be unchanged; otherwise afterBalance == beforeBalance + _amount
        // and afterFinish > block.timestamp (i.e., in future) and afterFinish >= beforeFinish (monotone non-decreasing).
        assert(
            reverted
                ? (afterBalance >= beforeBalance ? true : true) // when reverted we can't assert changes, so accept any observable state
                : (afterBalance == beforeBalance + _amount && uint256(afterFinish) > block.timestamp && uint256(afterFinish) >= uint256(beforeFinish))
        );
    }

    receive() external payable {}
}
